{
  "query": "{ hogwarts { houseRoster { total items { name animal members { name type subject } } } } }"
}

{
  "query": "query Find($name: String) { hogwarts { wizardOverview(nameLike: $name, size: 1) { total items { name house { name } } } } }",
  "variables": {
    "name": "%Lovegood"
  }
}

{
  "query": "{ hogwarts { spellBook(nameLike: \"Expelliarmus\") { items { name casters { level favourite wizard { name type house { name } } } } } } }"
}

{
  "name": "Gilderoy Lockhart {{runId}}",
  "yearOfBirth": 1964,
  "subject": "Defence Against the Dark Arts",
  "wand": {
    "wood": "Cherry",
    "core": "Dragon heartstring",
    "lengthInches": 9
  },
  "houseId": "{{ravenclawId}}"
}
